<script setup lang="ts">
import { CalendarClock, ChevronLeft, ChevronRight, MapPin, Plus, Users } from '@lucide/vue';
import { calendarDay, meetingMonthDays, meetingKind, meetingResponse, type CrmMeeting } from '~/shared/crm-meetings';
const props=defineProps<{items:CrmMeeting[];month:string;day:string;canCreate:boolean;loading:boolean}>();
const emit=defineEmits<{day:[day:string];month:[month:string];open:[meeting:CrmMeeting];create:[day:string]}>();
const days=computed(()=>meetingMonthDays(props.month)),today=calendarDay(new Date());
const events=(day:Date)=>props.items.filter(m=>new Date(m.startsAt)<new Date(day.getFullYear(),day.getMonth(),day.getDate()+1)&&new Date(m.endsAt)>day);
const agenda=computed(()=>props.day?events(new Date(props.day+'T00:00:00')):[]);
const caption=computed(()=>props.month?new Date(props.month+'-01T12:00:00').toLocaleDateString('ru-RU',{month:'long',year:'numeric'}):'Календарь');
const dayCaption=computed(()=>props.day?new Date(props.day+'T12:00:00').toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'}):'Выберите день');
const time=(value:string)=>new Date(value).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});
const dayLabel=(date:Date)=>date.toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})+` · событий: ${events(date).length}`;
function shift(offset:number){const d=new Date(props.month+'-01T12:00:00');d.setMonth(d.getMonth()+offset);emit('month',calendarDay(d).slice(0,7));}
</script>
<template>
 <section class="crm-surface meeting-calendar" aria-label="Календарь мероприятий и совещаний" :aria-busy="loading">
  <header class="meeting-calendar-head"><div><CalendarClock :size="21"/><h2>{{caption}}</h2></div><div><button class="crm-button crm-button--icon" aria-label="Предыдущий месяц" :disabled="loading" @click="shift(-1)"><ChevronLeft :size="18"/></button><button class="crm-button" :disabled="loading" @click="emit('month',today.slice(0,7));emit('day',today)">Сегодня</button><button class="crm-button crm-button--icon" aria-label="Следующий месяц" :disabled="loading" @click="shift(1)"><ChevronRight :size="18"/></button></div></header>
  <div class="meeting-calendar-layout">
   <div class="meeting-month"><div class="meeting-weekdays"><span v-for="day in ['Пн','Вт','Ср','Чт','Пт','Сб','Вс']" :key="day">{{day}}</span></div>
    <div class="meeting-month-grid"><div v-for="date in days" :key="calendarDay(date)" class="meeting-day" :class="{'is-selected':day===calendarDay(date),'is-outside':calendarDay(date).slice(0,7)!==month,'is-today':calendarDay(date)===today}">
     <button class="meeting-day-number crm-card-action" :aria-label="dayLabel(date)" :aria-pressed="day===calendarDay(date)" :aria-current="calendarDay(date)===today?'date':undefined" :disabled="loading" @click="emit('day',calendarDay(date))"><span>{{date.getDate()}}</span><i v-if="events(date).length">{{events(date).length}}</i></button>
     <button v-for="event in events(date).slice(0,2)" :key="event.id" class="meeting-day-event crm-card-action" :class="{'is-cancelled':event.status==='CANCELLED'}" :disabled="loading" :title="event.title" @click="emit('open',event)"><time>{{time(event.startsAt)}}</time><span>{{event.title}}</span></button>
     <button v-if="events(date).length>2" class="meeting-day-more crm-card-action" :disabled="loading" @click="emit('day',calendarDay(date))">Ещё {{events(date).length-2}}</button>
    </div></div>
   </div>
   <aside class="meeting-day-agenda" aria-label="События выбранного дня"><header><h3>{{dayCaption}}</h3><button v-if="canCreate" class="crm-button crm-button--icon" :disabled="loading" aria-label="Создать событие в выбранный день" @click="emit('create',day)"><Plus :size="18"/></button></header>
    <p v-if="!agenda.length&&!loading" class="meeting-calendar-empty">{{canCreate?'На этот день событий нет. Выберите другую дату или создайте событие.':'На этот день событий нет. Выберите другую дату.'}}</p>
    <button v-for="event in agenda" :key="event.id" class="meeting-agenda-event crm-card-action" :disabled="loading" @click="emit('open',event)"><span class="meeting-agenda-time">{{time(event.startsAt)}} — {{time(event.endsAt)}}</span><strong>{{event.title}}</strong><small>{{meetingKind(event.kind)}} · {{event.status==='CANCELLED'?'Отменено':event.myResponse?meetingResponse(event.myResponse):'Запланировано'}}</small><span v-if="event.location"><MapPin :size="14"/>{{event.location}}</span><span v-else-if="event.meetingUrl">Онлайн</span><span><Users :size="14"/>{{event.members.length+1}} участников<span v-if="event.responses"> · подтвердили {{event.responses.accepted}}</span></span></button>
   </aside>
  </div>
 </section>
</template>
<style scoped>
@layer crm-elements {
.meeting-calendar{overflow:hidden}.meeting-calendar-head,.meeting-calendar-head>div{display:flex;align-items:center;gap:12px}.meeting-calendar-head{padding:20px;justify-content:space-between;flex-wrap:wrap;border-bottom:1px solid var(--crm-line)}.meeting-calendar-head h2{margin:0;text-transform:capitalize;font-size:20px}.meeting-calendar-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px}.meeting-month{min-width:0}.meeting-weekdays,.meeting-month-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr))}.meeting-weekdays{background:var(--crm-bg)}.meeting-weekdays span{padding:12px;text-align:center;color:var(--crm-muted);font-size:12px}.meeting-day{min-width:0;min-height:110px;padding:6px;background:var(--crm-surface);border-top:1px solid var(--crm-line);border-right:1px solid var(--crm-line)}.meeting-day.is-outside{background:var(--crm-bg)}.meeting-day.is-outside .meeting-day-number{color:var(--crm-muted)!important}.meeting-day.is-selected{box-shadow:inset 0 0 0 2px var(--crm-accent)}.meeting-day-number{display:flex!important;justify-content:space-between!important;align-items:center;width:100%;padding:4px!important;border:0!important;background:transparent!important;color:var(--crm-ink)!important;text-align:left!important;min-height:30px!important}.meeting-day-number>span{display:grid;place-items:center;width:27px;height:27px;border-radius:50%}.is-today .meeting-day-number>span{background:var(--crm-ink);color:var(--crm-surface)}.meeting-day-number i{font-size:10px;font-style:normal;color:var(--crm-muted)}.meeting-day-event{display:flex!important;align-items:baseline!important;gap:4px;width:100%;padding:5px 4px!important;margin-top:4px;border:0!important;border-radius:4px!important;background:var(--crm-tint)!important;color:var(--crm-ink)!important;font-size:10px!important;text-align:left!important;min-height:0!important}.meeting-day-event span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.meeting-day-event time{font-size:9px;flex-shrink:0}.is-cancelled{text-decoration:line-through;opacity:.65}.meeting-day-more{border:0!important;background:transparent!important;color:var(--crm-ink)!important;font-size:10px!important;padding:5px!important;min-height:0!important}.meeting-day-agenda{padding:18px;min-width:0}.meeting-day-agenda>header{display:flex;align-items:center;justify-content:space-between;gap:10px}.meeting-day-agenda h3{font-size:15px;margin:0;text-transform:capitalize}.meeting-calendar-empty{color:var(--crm-muted);font-size:13px;line-height:1.7;margin-top:24px}.meeting-agenda-event{display:flex!important;align-items:start!important;flex-direction:column;gap:10px;width:100%;margin-top:16px;padding:16px!important;border:1px solid var(--crm-line)!important;background:var(--crm-bg)!important;color:var(--crm-ink)!important;text-align:left!important;border-radius:10px;white-space:normal!important;overflow-wrap:anywhere}.meeting-agenda-event:hover,.meeting-day-event:hover{box-shadow:inset 0 0 0 1px var(--crm-accent)}.meeting-agenda-time{font-size:12px;color:var(--crm-muted)}.meeting-agenda-event strong{font-size:14px}.meeting-agenda-event small,.meeting-agenda-event>span:not(.meeting-agenda-time){font-size:12px;display:flex;gap:5px;align-items:start;flex-wrap:wrap}.meeting-agenda-event svg{flex-shrink:0}.meeting-agenda-event small{color:var(--crm-muted)}
@media(max-width:1150px){.meeting-calendar-layout{grid-template-columns:minmax(0,1fr)}.meeting-day-agenda{border-top:1px solid var(--crm-line)}}@media(max-width:600px){.meeting-calendar-head{padding:14px;gap:14px}.meeting-calendar-head h2{font-size:17px}.meeting-day{min-height:64px;padding:3px}.meeting-day-event{display:none!important}.meeting-day-more{display:none!important}.meeting-weekdays span{padding:9px 0;font-size:11px}.meeting-day-number{flex-direction:column;gap:3px}.meeting-day-number i{background:var(--crm-tint);min-width:18px;text-align:center;border-radius:4px}.meeting-day-agenda{padding:16px}}
}
</style>
